// ---------------------------------------------------------------------
// Lookup helpers
// ---------------------------------------------------------------------

/**
 * Find the nodeId whose coordinate lies within `tolerance` of (x, y).
 * Returns the nodeId string, or null when nothing is close enough.
 */
function getNodeAtPoint(x, y, tolerance = 8) {
  let bestId = null;
  let bestDist = Infinity;
  for (const id in BOARD_NODES) {
    const n = BOARD_NODES[id];
    const dx = n.x - x;
    const dy = n.y - y;
    if (Math.abs(dx) > tolerance || Math.abs(dy) > tolerance) continue;
    const dist = dx * dx + dy * dy;
    if (dist < bestDist) {
      bestDist = dist;
      bestId = id;
    }
  }
  return bestId;
}

/** Return {x, y} for a given nodeId, or null when unknown. */
function getPointForNode(nodeId) {
  const n = BOARD_NODES[nodeId];
  return n ? { x: n.x, y: n.y } : null;
}

/** Node type recorded at extraction time ("hole" | "led" | "switch" | ...). */
function getNodeType(nodeId) {
  const m = BOARD_NODE_META[nodeId];
  return m ? m.type : null;
}

/** Full static metadata object (or null). */
function getNodeMeta(nodeId) {
  return BOARD_NODE_META[nodeId] || null;
}

/** True when the nodeId exists on the board. */
function hasNode(nodeId) {
  return Object.prototype.hasOwnProperty.call(BOARD_NODES, nodeId);
}

// ---------------------------------------------------------------------
// Breadboard internal connectivity
// ---------------------------------------------------------------------
// The five IC bases behave like classic solderless breadboard strips: each
// base carries two columns of ten holes (L = left, R = right) and every hole
// forms its own tie point, so nets collapse per board+column+row.  Two wires
// plugged into the same hole therefore share one logical node -- exactly what
// lets an IC pin be tapped without a second wire.
//
// Net keys produced:
//   "net-bb<board>-<SIDE><row>"        e.g. "net-bb1-L5"
//   "net-rail-vcc" / "net-rail-gnd"    fixed supply rails
//   "net-rail-high" / "net-rail-low"   fixed logic levels
//   "net-<nodeId>"                     everything else is its own net

function getBreadboardNet(nodeId) {
  if (!nodeId) return null;

  // Fixed rails keep a stable identity no matter how they are wired.
  if (nodeId === "pin-out-vcc") return "net-rail-vcc";
  if (nodeId === "pin-gnd") return "net-rail-gnd";
  if (nodeId === "pin-high") return "net-rail-high";
  if (nodeId === "pin-low") return "net-rail-low";

  const m = /^hole-bb(\d+)-([LR])(\d+)$/.exec(nodeId);
  if (m) return "net-bb" + m[1] + "-" + m[2] + m[3];

  return "net-" + nodeId;
}

/** All nodeIds sharing the same internal net as `nodeId`. */
function getNodesInNet(nodeId) {
  const key = getBreadboardNet(nodeId);
  const out = [];
  for (const id in BOARD_NODES) {
    if (getBreadboardNet(id) === key) out.push(id);
  }
  return out;
}

/**
 * Map datasheet DIP pins onto a 20-position IC base.
 *
 * Pin 1 starts at the upper-left. The left side numbers downward; the right
 * side numbers upward, so the highest-numbered pin is at upper-right.
 * Example: DIP-14 => 1..7 map to L1..L7 and 8..14 map to R4..R10.
 */
function getICPinHoleMap(slotIndex, pinCount) {
  if (!Number.isInteger(slotIndex) || slotIndex < 1 || slotIndex > 5) {
    throw new RangeError("IC slot must be between 1 and 5");
  }
  if (!Number.isInteger(pinCount) || pinCount < 2 || pinCount > 20 || pinCount % 2 !== 0) {
    throw new RangeError("IC pin count must be an even number from 2 to 20");
  }

  const half = pinCount / 2;
  const map = {};
  for (let pin = 1; pin <= half; pin++) {
    const hole = `hole-bb${slotIndex}-L${pin}`;
    if (hasNode(hole)) map[pin] = hole;
  }
  for (let pin = half + 1; pin <= pinCount; pin++) {
    const row = 10 - pinCount + pin;
    const hole = `hole-bb${slotIndex}-R${row}`;
    if (hasNode(hole)) map[pin] = hole;
  }
  return map;
}

// Export for headless tooling/tests; harmless in the browser.
if (typeof module !== "undefined" && module.exports) {
  module.exports = {
    BOARD_NODES,
    BOARD_NODE_META,
    getNodeAtPoint,
    getPointForNode,
    getNodeType,
    getNodeMeta,
    hasNode,
    getBreadboardNet,
    getNodesInNet,
    getICPinHoleMap,
  };
}
